  const init=()=>({mounted:true,query:"",current:null,loading:false,result:null,error:null});
  let s=state==null?init():state;
  let effects=[];
  const out=()=>({mounted:s.mounted,query:s.query,current:s.current,loading:s.loading,result:s.result,error:s.error,effects});
  if(!s.mounted){
    if(event&&event.type==="mount")s=init();
    return {state:s,output:out()};
  }
  if(!event||typeof event!=="object")return {state:s,output:out()};
  if(event.type==="search"){
    if(s.loading)effects.push({type:"cancel",id:s.current});
    s.current=event.id;s.query=event.query;s.loading=true;s.error=null;
    effects.push({type:"request",id:event.id,query:event.query});
  }else if(event.type==="success"){
    if(s.loading&&s.current===event.id){s.result=event.result;s.error=null;s.loading=false;}
  }else if(event.type==="failure"){
    if(s.loading&&s.current===event.id){s.error=event.error;s.loading=false;}
  }else if(event.type==="cancel"){
    if(s.loading)effects.push({type:"cancel",id:s.current});
    s.loading=false;s.current=null;s.error=null;
  }else if(event.type==="dispose"){
    if(s.loading)effects.push({type:"cancel",id:s.current});
    s=init();s.mounted=false;
  }
  return {state:s,output:out()};
}"}
